command:
set -eu; export VAULT_ADDR="https://${NODE_IP}:8200" VAULT_CACERT=/etc/vault.d/tls/ca.crt; VAULT_TOKEN=[REDACTED] -r '.root_token' /root/transit-init.json); export VAULT_TOKEN; vault secrets list -format=json | jq -e 'has("transit/")' >/dev/null || vault secrets enable -path=transit transit >/dev/null; vault write -f transit/keys/autounseal >/dev/null; cat > /tmp/autounseal-policy.hcl <<'EOF'
path "transit/encrypt/autounseal" {
  capabilities = ["update"]
}
path "transit/decrypt/autounseal" {
  capabilities = ["update"]
}
EOF
vault policy write autounseal /tmp/autounseal-policy.hcl >/dev/null; seal_token=[REDACTED]$CLUSTER_SSH_PRIVKEY" | openssl dgst -sha256 -hmac 'infraset-vault-transit-seal' | awk '{print $2}')"; vault token create -id="$seal_token" -display-name=raft-auto-unseal -policy=autounseal -orphan -period=24h >/dev/null; export VAULT_TOKEN=[REDACTED]; unset seal_token; printf 'engine='; vault secrets list -format=json | jq -r '."transit/".type'; printf 'key='; vault read -format=json transit/keys/autounseal | jq -r '.data.name'; printf 'encrypt_capability='; vault token capabilities transit/encrypt/autounseal; printf 'decrypt_capability='; vault token capabilities transit/decrypt/autounseal

